(function(){'use strict';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const selected=new Set();
const link=document.createElement('details');link.id='conversation-link';link.className='data-section';link.innerHTML='<summary>会話で気づいたことを、自分で記録につなげる</summary><label for="link-message">整理したい発言を選ぶ</label><select id="link-message"><option value="">まだ選ばない</option></select><div class="form-actions"><button id="link-aspiration" type="button">ありたい姿・気になることに整理する</button><button id="link-plan" type="button">試す内容の候補として開く</button></div><p class="quiet">選んでも自動保存しません。自分の言葉に編集し、状態を選んで保存できます。何も作らず終えても大丈夫です。</p>';
$('live-candidate').after(link);
const sharing=document.createElement('section');sharing.className='data-section';sharing.innerHTML='<h2>次の対話に、どの記録を使う？</h2><p>本人が確認して保存した内容だけを、チェックした記録から共有候補にします。送信前に毎回、本文を確認できます。AI仮説や外部アプリの記録は含めません。</p><div id="cycle-records"></div><button id="clear-shared" type="button">共有の選択をすべて外す</button><a href="#dialogue">選んだ記録について話す →</a>';
$('screen-memory').insertBefore(sharing,$('screen-memory').querySelector('.data-section'));
const tools=document.createElement('section');tools.className='data-section';tools.innerHTML='<h2>応答の記録と、気になる回答。</h2><p>費用の最小監査情報と応答原文は別に扱います。原文は送信時に許可した場合だけ暗号化して最大20件保持し、24時間後はアクセスできません。期限切れ原文は次の起動・監査・保存操作時に削除します。同じWindows利用者が鍵にアクセスできるため、本番の秘密保護や実認証を満たすものではありません。</p><div class="form-actions"><button id="load-audit" type="button">この利用者の監査情報を確認</button><button id="revoke-raw" type="button">原文保存の同意を撤回・原文を削除</button></div><div id="audit-records"></div><textarea id="audit-export" rows="6" readonly aria-label="原文の本人向け書き出し" hidden></textarea><h3>気になるAI回答を端末内に報告メモとして残す</h3><label for="report-message">対象のAI回答</label><select id="report-message"><option value="">選択してください</option></select><label for="report-reason">どこが気になった？（500文字以内）</label><textarea id="report-reason" maxlength="500" rows="3"></textarea><button id="save-report" type="button">端末内にメモを残す</button><p class="quiet">運営・専門家へは送信しません。サーバーを停止すると消えるため、必要なら会話JSONに書き出してください。試験運営の報告受付体制は未実装です。</p><p id="report-status" role="status"></p><button id="delete-live-open" type="button">サーバーの会話を削除する</button>';
$('screen-memory').append(tools);
const rawLabel=document.createElement('label');rawLabel.className='check-label';rawLabel.innerHTML='<input id="retain-raw" type="checkbox">調査用に応答原文をこの端末へ暗号化保存する（任意・24時間後アクセス不可）。初期状態は保存しません。';$('live-consent').querySelector('.form-actions').before(rawLabel);
const length=document.createElement('div');length.innerHTML='<label for="response-style">回答の希望</label><select id="response-style"><option value="auto">言葉に合わせる</option><option value="short">結論を短く</option><option value="explain">理由・根拠候補・条件を知りたい</option></select>';$('home-form').after(length);
const del=document.createElement('dialog');del.setAttribute('aria-labelledby','delete-live-title');del.innerHTML='<h2 id="delete-live-title">サーバーの会話を削除しますか？</h2><p>この会話・仮説・本人確認・報告メモと、許可して保存した応答原文を削除します。計画・経験の手入力保存とは別です。本文を含まない費用監査情報と消費済み予算は保持します。</p><div class="form-actions"><button id="delete-live-confirm" type="button">内容を確認して削除する</button><button id="delete-live-cancel" type="button">戻る</button></div>';document.body.append(del);
function notify(t){window.WHYAppBridge.notify(t)}
function render(){const records=window.WHYAppBridge.records(),live=window.WHYLive.current();$('cycle-records').innerHTML=records.length?records.map(r=>'<label class="check-label"><input type="checkbox" data-share-record="'+esc(r.id)+'" '+(selected.has(r.id)?'checked':'')+'>'+esc(({aspiration:'ありたい姿',plan:'試してみること',experience:'経験'}[r.kind]))+'：'+esc(r.values.text||r.values.title||r.values.actual)+'<span class="quiet">（試験用・操作して確認／外部未確認）</span></label>').join(''):'<p class="quiet">保存した内容はまだありません。共有や目標設定は必須ではありません。</p>';
 const msg=live?.messages?.filter(m=>m.status==='current')||[],keep=$('link-message').value;$('link-message').innerHTML='<option value="">まだ選ばない</option>'+msg.map(m=>'<option value="'+esc(m.id)+'">'+(m.role==='user'?'自分':'AI候補')+'：'+esc(m.text.slice(0,55))+'</option>').join('');if(msg.some(m=>m.id===keep))$('link-message').value=keep;
 const reportKeep=$('report-message').value;$('report-message').innerHTML='<option value="">選択してください</option>'+msg.filter(m=>m.role==='assistant').map(m=>'<option value="'+esc(m.id)+'">'+esc(m.text.slice(0,70))+'</option>').join('');if(msg.some(m=>m.id===reportKeep))$('report-message').value=reportKeep;
 $('report-status').textContent=live?.reports?.length?'端末内の報告メモ：'+live.reports.length+'件。外部送信なし。':'';}
function chosen(){const id=$('link-message').value,m=window.WHYLive.current()?.messages.find(m=>m.id===id&&m.status==='current');if(!m)notify('整理する発言を先に選んでください。');return m}
$('link-aspiration').addEventListener('click',()=>{const m=chosen();if(m)window.WHYAppBridge.prepareAspiration(m.text,m.id)});$('link-plan').addEventListener('click',()=>{const m=chosen();if(m)window.WHYAppBridge.preparePlan(m.text,m.id)});
$('cycle-records').addEventListener('change',e=>{const id=e.target.dataset.shareRecord;if(!id)return;if(e.target.checked)selected.add(id);else selected.delete(id);window.dispatchEvent(new Event('why-sharing-changed'))});$('clear-shared').addEventListener('click',()=>{selected.clear();render();window.dispatchEvent(new Event('why-sharing-changed'))});
$('load-audit').addEventListener('click',async()=>{try{const data=await window.WHYLive.getAudit();$('audit-records').innerHTML=data.records.map(r=>'<div class="memory-row"><p>'+esc(r.provenance==='offline-fixture'?'ローカル試験':'実通信の受信情報')+' / '+esc(r.phase)+'</p><p>使用量：'+(r.usage?esc(r.usage.input_tokens)+'入力 / '+esc(r.usage.output_tokens)+'出力':'未取得')+' / 検証：'+esc(r.validation.state)+'</p><p>費用換算：'+(r.accounting.estimateMicroUSD===null?'未確定・予約枠を保持':'US$'+(r.accounting.estimateMicroUSD/1e6).toFixed(6)+'（請求未照合・ローカル試験は実課金なし）')+'</p><p>原文：'+esc(r.raw.state)+'</p>'+(r.raw.state==='retained'?'<button type="button" data-export-raw="'+r.id+'">自分の原文を表示する</button>':'')+'</div>').join('')||'<p>この利用者の監査情報はまだありません。</p>'}catch(e){notify(e.message)}});
$('audit-records').addEventListener('click',async e=>{const id=e.target.dataset.exportRaw;if(!id)return;try{const r=await window.WHYLive.exportRaw(id);$('audit-export').hidden=false;$('audit-export').value=r.raw}catch(e){notify(e.message)}});
$('revoke-raw').addEventListener('click',async()=>{try{await window.WHYLive.revokeRaw();$('audit-export').value='';$('audit-export').hidden=true;$('audit-records').textContent='原文保存の同意を撤回しました。費用メタデータは保持します。'}catch(e){notify(e.message)}});
$('save-report').addEventListener('click',async()=>{try{await window.WHYLive.report($('report-message').value,$('report-reason').value);$('report-reason').value='';render();notify('報告メモを端末内だけに残しました。運営へは送信していません。')}catch(e){notify(e.message)}});
$('delete-live-open').addEventListener('click',()=>{del.showModal();$('delete-live-cancel').focus()});$('delete-live-cancel').addEventListener('click',()=>del.close());$('delete-live-confirm').addEventListener('click',async()=>{await window.WHYLive.deleteConversation();del.close();$('audit-records').textContent='会話と応答原文を削除しました。';render();notify('サーバーの会話と原文を削除しました。手入力の記録・消費済み予算は変えていません。')});
window.addEventListener('why-data-changed',render);window.addEventListener('why-live-updated',render);
window.WHYCycle={selectOnly(ids){selected.clear();window.WHYAppBridge.records().filter(r=>ids.includes(r.id)).forEach(r=>selected.add(r.id));render();window.dispatchEvent(new Event("why-sharing-changed"));},shared(){return window.WHYAppBridge.records().filter(r=>selected.has(r.id))},style(){return $('response-style').value},rawConsent(){return $('retain-raw').checked},clearRawConsent(){if($('retain-raw'))$('retain-raw').checked=false}};render();
})();
